from __future__ import annotations

from dataclasses import dataclass


def _non_empty(field: str, value: str) -> None:
    if not value.strip():
        raise ValueError(f"{field} required")


@dataclass(frozen=True)
class S3InventoryObject:
    key: str
    size_kb: int
    age_days: int
    storage_class: str
    current_monthly_cost_cents: int
    expires_in_days: int | None = None

    def __post_init__(self) -> None:
        _non_empty("key", self.key)
        if self.size_kb < 0:
            raise ValueError("size_kb must be non-negative")
        if self.age_days < 0:
            raise ValueError("age_days must be non-negative")
        _non_empty("storage_class", self.storage_class)
        if self.current_monthly_cost_cents < 0:
            raise ValueError("current_monthly_cost_cents must be non-negative")
        if self.expires_in_days is not None and self.expires_in_days < 0:
            raise ValueError("expires_in_days must be non-negative")

    def inventory_coordinates(self) -> tuple[str, int]:
        return (self.key.strip(), self.age_days)


@dataclass(frozen=True)
class LifecycleRule:
    transition_after_days: int
    target_storage_class: str
    target_monthly_cost_cents: int
    transition_request_cost_cents: int
    minimum_object_size_kb: int
    minimum_storage_duration_days: int

    def __post_init__(self) -> None:
        if self.transition_after_days < 0:
            raise ValueError("transition_after_days must be non-negative")
        _non_empty("target_storage_class", self.target_storage_class)
        if self.target_monthly_cost_cents < 0:
            raise ValueError("target_monthly_cost_cents must be non-negative")
        if self.transition_request_cost_cents < 0:
            raise ValueError("transition_request_cost_cents must be non-negative")
        if self.minimum_object_size_kb < 0:
            raise ValueError("minimum_object_size_kb must be non-negative")
        if self.minimum_storage_duration_days < 0:
            raise ValueError("minimum_storage_duration_days must be non-negative")

    def cost_floor_cents(self) -> int:
        return self.target_monthly_cost_cents


def normalize_storage_class(storage_class: str) -> str:
    return storage_class.strip().upper().replace(" ", "_")


def is_glacier_family(normalized_class: str) -> bool:
    return "GLACIER" in normalized_class or normalized_class.startswith("DEEP_ARCHIVE")


def inventory_row_bytes_hint(size_kb: int) -> int:
    return max(0, size_kb) * 1024


def storage_tier_label(raw_class: str) -> str:
    return normalize_storage_class(raw_class)


def lifecycle_rule_fingerprint(rule: LifecycleRule) -> str:
    return "|".join(
        (
            str(rule.transition_after_days),
            normalize_storage_class(rule.target_storage_class),
            str(rule.minimum_object_size_kb),
        )
    )

