from __future__ import annotations

"""Minimum storage duration and FinOps-style exposure estimates for S3 lifecycle previews."""

from s3_inventory import LifecycleRule, S3InventoryObject, normalize_storage_class

DAYS_PER_MONTH_MODEL = 30


def format_skip_reason_label(reason: str) -> str:
    return reason.strip()


def compute_minimum_duration_exposure_cents(obj: S3InventoryObject, rule: LifecycleRule) -> int:
    if obj.expires_in_days is None or obj.expires_in_days >= rule.minimum_storage_duration_days:
        return 0
    missing_days = rule.minimum_storage_duration_days - obj.expires_in_days
    return round(rule.target_monthly_cost_cents * missing_days / DAYS_PER_MONTH_MODEL)


def expires_before_minimum_duration(obj: S3InventoryObject, rule: LifecycleRule) -> bool:
    if obj.expires_in_days is None:
        return False
    return obj.expires_in_days < rule.minimum_storage_duration_days


def lifetime_after_transition_days(obj: S3InventoryObject, rule: LifecycleRule) -> int | None:
    if obj.expires_in_days is None:
        return None
    return max(0, obj.expires_in_days - rule.transition_after_days)


def describe_duration_gap(rule: LifecycleRule, expires_in_days: int | None) -> str:
    if expires_in_days is None:
        return "no_expiration_metadata"
    if expires_in_days >= rule.minimum_storage_duration_days:
        return "satisfies_minimum"
    return f"expires_in_{expires_in_days}_before_{rule.minimum_storage_duration_days}"


def prorated_monthly_fraction(days: int) -> float:
    if days < 0:
        raise ValueError("days must be non-negative")
    return days / DAYS_PER_MONTH_MODEL


def transition_savings_delta_cents(current_cents: int, target_cents: int) -> int:
    return max(0, current_cents - target_cents)


def net_month_one_cents(savings_cents: int, request_cost_cents: int) -> int:
    return savings_cents - request_cost_cents


def rule_duration_summary(rule: LifecycleRule) -> dict[str, int]:
    return {
        "transition_after_days": rule.transition_after_days,
        "minimum_storage_duration_days": rule.minimum_storage_duration_days,
        "minimum_object_size_kb": rule.minimum_object_size_kb,
    }


def object_meets_transition_age(obj: S3InventoryObject, rule: LifecycleRule) -> bool:
    return obj.age_days >= rule.transition_after_days


def object_meets_size_floor(obj: S3InventoryObject, rule: LifecycleRule) -> bool:
    return obj.size_kb >= rule.minimum_object_size_kb


def rule_transition_label(rule: LifecycleRule) -> str:
    return f"{rule.transition_after_days}d->{normalize_storage_class(rule.target_storage_class)}"


def exposure_proration_note(missing_days: int, monthly_cents: int) -> str:
    return f"gap={missing_days}d bill≈{monthly_cents}c/mo"


def candidate_eligible_months_hint(obj: S3InventoryObject, rule: LifecycleRule) -> float:
    if obj.expires_in_days is None:
        return float("inf")
    return max(0.0, obj.expires_in_days / DAYS_PER_MONTH_MODEL)


def transition_request_amortized_hint(request_cents: int, hold_months: float) -> float:
    if hold_months <= 0:
        return float(request_cents)
    return request_cents / hold_months

